CREATE TABLE rv_auth_attempt (dimension SMALLINT NOT NULL CHECK (dimension BETWEEN 1 AND 10), bucket INTEGER NOT NULL CHECK (bucket >= 0 AND bucket < 1048576), window_start DATETIME(6) NOT NULL, current_count BIGINT NOT NULL CHECK (current_count >= 0), previous_count BIGINT NOT NULL CHECK (previous_count >= 0), expires_at DATETIME(6) NOT NULL, PRIMARY KEY (dimension, bucket));
